function CommonMicBtn:Awake()
    self:SetBtnState(false)
    ---@type Social
    self.socialLine = AppService:GetInstance():GetSocialLine()
    self:AddListener()
    UIEventProxy.Create(self.RT_Area.gameObject).onPointerClick = function()
        local result = self.socialLine:SetMicState(not self.openState, self.playerId)
        if result ~= 0 then
            if result == 1201 then
                GameUtils.Toast(localize("等待加入语音聊天房间"))
            else
                GameUtils.Toast(localize("麦克风状态设置失败 err:_num_", {_num_ = result}))
            end
        end
    end
end

