function CommonMicBtn:CleanProperties()
    self.openState = nil
    self.socialLine = nil
    self.playerId = nil
    self.callbackOnBtnStateChanged = nil
    self.eventVoiceStateChanged = nil
    self.eventVoiceEnterRoom = nil
    self.eventVoiceEvent = nil
end

function CommonMicBtn:AddListener()
    self.eventVoiceStateChanged = Events.AddListener(Constants.EventNames.VOICE_ROOM_MEMBERS, Bind(self, self.OnVoiceStateChanged))
    self.eventVoiceEnterRoom = Events.AddListener(Constants.EventNames.VOICE_ENTER_ROOM, Bind(self, self.OnVoiceEnterRoom))
    self.eventVoiceEvent = Events.AddListener(Constants.EventNames.VOICE_EVENT, Bind(self, self.OnVoiceEvent))
end

function CommonMicBtn:RemoveListener()
    Events.RemoveListener(Constants.EventNames.VOICE_ROOM_MEMBERS, self.eventVoiceStateChanged)
    Events.RemoveListener(Constants.EventNames.VOICE_ENTER_ROOM, self.eventVoiceEnterRoom)
    Events.RemoveListener(Constants.EventNames.VOICE_EVENT, self.eventVoiceEvent)
end

--- 加入语音聊天房间结束回调
---@param code any
---@param errorInfo any
function CommonMicBtn:OnVoiceEnterRoom(code, errorInfo)
    code = checkNumber(code)
    if code == 0
    or code == 1003 then
        -- if isNotNull(self.playerId) then
        --     self:RefreshBtnState()
        -- end
    else
        GameUtils.Toast(localize("加入语音聊天房间失败 code:_num_ info:_str_", {_num_ = code, _str_ = tostring(errorInfo)}))
    end
end

--- 语音状态变化回调
---@param eventID any
---@param count any
---@param identifiers any
function CommonMicBtn:OnVoiceStateChanged(eventID, count, identifiers)
    local length = identifiers.Length
    for i = 0, length - 1, 1 do
        if checkNumber(identifiers[i]) == self.playerId then
            if eventID == 11 then
                self:SetBtnState(true)
            elseif eventID == 12 then
                self:SetBtnState(false)
            end
        end
        print("[语音] 麦克风开关按钮", checkNumber(identifiers[i]), eventID, count)
    end
end

--- 语音事件
---@param type any
---@param subType any
---@param data any
function CommonMicBtn:OnVoiceEvent(type, subType, data)
    if type == 6000 and subType == 6 then
        if isNotNull(data) and isNotNull(data.Result) and data.Result == 0 then     -- 请求成功
            if isNotNull(data.isACK) and data.isACK == true     -- 是应答消息
            and isNotNull(data.ReceiverID) and checkNumber(data.ReceiverID) == self.playerId then       -- 是请求的这个玩家
                -- 请求指定玩家的麦克风状态时的回复事件
                if isNotNull(data.OperateValue) then
                    self:SetBtnState(data.OperateValue)
                    -- print("[语音] 麦克风状态")
                end
            end
        end
    end
end

function CommonMicBtn:SetPlayerId(id)
    self.playerId = id
end

function CommonMicBtn:SetCallbackOnBtnStageChanged(callback)
    self.callbackOnBtnStateChanged = callback
end

function CommonMicBtn:SetBtnState(boolean)
    self.openState = boolean
    KTool.SetActive(self.RT_ImgOpen, self.openState)
    KTool.SetActive(self.RT_ImgClose, not self.openState)
    if isNotNull(self.callbackOnBtnStateChanged) then
        self.callbackOnBtnStateChanged(self.openState)
    end
end

return CommonMicBtn